<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {hostBytes} from './hostBilling'
const props=defineProps<{api:(p:string,m?:string,b?:any)=>Promise<any>,userId?:string,users?:Record<string,any>[],expanded:boolean}>(),emit=defineEmits<{'update:expanded':[boolean],'update:userId':[string]}>()
const root=ref<HTMLElement|null>(null),rows=ref<Record<string,any>[]>([]),page=ref(1),pages=ref(1),total=ref(0),sort=ref('time'),order=ref('desc'),search=ref(''),busy=ref(false),error=ref(''),last=ref('')
let alive=true,visible=true,sequence=0,timer:ReturnType<typeof setInterval>,observer:IntersectionObserver|undefined
async function load(){if(!props.expanded)return;const seq=++sequence;busy.value=true;error.value='';try{const q=new URLSearchParams({page:String(page.value),limit:'50',sort:sort.value,order:order.value});if(props.userId)q.set('user_id',props.userId);if(search.value.trim())q.set('search',search.value.trim());const r=await props.api('access-records/page?'+q);if(!alive||seq!==sequence)return;rows.value=r.items??[];total.value=r.total??0;pages.value=r.pages??1;if(page.value>pages.value){page.value=pages.value;return};last.value=new Date().toLocaleTimeString()}catch(e){if(alive&&seq===sequence)error.value=String(e)}finally{if(alive&&seq===sequence)busy.value=false}}
watch(()=>[props.expanded,props.userId,sort.value,order.value],()=>{page.value=1;if(props.expanded)void load()});watch(page,()=>void load())
function searchNow(){if(page.value===1)void load();else page.value=1}
onMounted(()=>{if(typeof IntersectionObserver!=='undefined'){observer=new IntersectionObserver(e=>{visible=!!e[0]?.isIntersecting});if(root.value)observer.observe(root.value)};if(props.expanded)void load();timer=setInterval(()=>{if(props.expanded&&visible&&document.visibilityState!=='hidden')void load()},30000)});onUnmounted(()=>{alive=false;sequence++;clearInterval(timer);observer?.disconnect()})
</script>
<template><section ref="root" class="panel publish-card access-log"><div class="section-heading"><div><span class="eyebrow">CONNECTION METADATA / LAST 7 DAYS</span><h2>访问目标与来源 IP</h2></div><button class="secondary" @click="emit('update:expanded',!expanded)">{{expanded?'收起访问记录':'展开访问记录'}}</button></div><p class="muted">仅显示代理连接元数据，每轮最多记录 100 条，最多保留 7 天 / 20,000 条。展开后可分页查询全部保留记录，按时间或连接流量排序；当前可见区域每 30 秒刷新。不包含 HTTPS 页面内容和完整 URL。内核没有提供分连接流量时显示“—”，不使用用户总量推算。</p><template v-if="expanded"><div class="record-controls"><label>筛选用户<select :value="userId??''" @change="emit('update:userId',($event.target as HTMLSelectElement).value)"><option value="">所有用户 / 共享入口</option><option v-for="u in users??[]" :key="u.id" :value="u.id">{{u.name}}</option></select></label><label>排序<select v-model="sort" aria-label="访问记录排序"><option value="time">连接时间</option><option value="traffic">连接使用流量</option></select></label><label>方向<select v-model="order"><option value="desc">从新到旧 / 从大到小</option><option value="asc">从旧到新 / 从小到大</option></select></label><form @submit.prevent="searchNow"><input v-model="search" aria-label="筛选目标或来源IP" placeholder="目标域名 / 来源 IP"><button class="secondary" :disabled="busy">查询</button></form></div><p v-if="error" class="error" role="alert">{{error}}</p><div class="record-scroll" tabindex="0" aria-label="连接记录滚动区域"><table><thead><tr><th>连接时间</th><th>用户 / 设备 / 入口</th><th>来源 IP</th><th>目标域名 / IP</th><th>上传 / 下载</th><th>连接流量</th></tr></thead><tbody><tr v-for="r in rows" :key="r.host_id+r.event_id"><td>{{new Date(r.observed_at).toLocaleString()}}<small class="block-muted">{{r.network?.toUpperCase()}} {{r.closed?'已结束':''}}</small></td><td>{{r.user_name||'共享密钥 / 未识别用户'}}<small class="block-muted">{{r.device_name||r.device_id||'通用身份'}} · {{r.host_name}} / {{r.service_name||'已移除入口'}}</small></td><td><code>{{r.source_ip}}</code></td><td>{{r.destination}}:{{r.destination_port}}</td><td>{{r.uplink==null?'—':hostBytes(r.uplink)}} / {{r.downlink==null?'—':hostBytes(r.downlink)}}</td><td>{{r.total_bytes==null?'—':hostBytes(r.total_bytes)}}</td></tr></tbody></table><p v-if="!rows.length&&!busy" class="console-empty">当前筛选没有连接记录。</p></div><div class="record-pages"><span>{{total}} 条 · 第 {{page}} / {{pages}} 页 · {{last?'更新 '+last:'等待查询'}}</span><div><button class="secondary" :disabled="busy||page<=1" @click="page--">上一页</button><button class="secondary" :disabled="busy||page>=pages" @click="page++">下一页</button><button class="text-button" :disabled="busy" @click="load">刷新当前页</button></div></div></template></section></template>
<style scoped>.record-controls{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0}.record-controls label{font-size:11px;display:grid;gap:6px}.record-controls form{display:flex;gap:8px;flex:1;min-width:190px}.record-controls select,.record-controls input{padding:9px;border:1px solid var(--border);background:var(--input);color:var(--ink);border-radius:7px;min-width:0}.record-controls input{width:100%}.record-scroll{max-height:430px;overflow:auto;border:1px solid var(--border);border-radius:10px}.record-scroll table{min-width:950px}.record-scroll thead{position:sticky;top:0;background:var(--panel);z-index:1}.record-pages{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:14px;font-size:12px;color:var(--muted)}.record-pages>div{display:flex;flex-wrap:wrap;gap:8px}.record-scroll td{max-width:240px;overflow-wrap:anywhere}@media(max-width:650px){.record-controls label{flex:1;min-width:125px}.record-pages>div{width:100%}.record-scroll{max-height:360px}}</style>
